  "common-chives": {
    "short": {
      "en": "Move an established cluster",
      "es": "Mueve un grupo establecido"
    },
    "guidance": {
      "en": "Johnny's starts chive plugs 6–8 weeks before the last frost and transplants the 3–4-seedling cluster. For Garden, use an upright cluster with active roots and leaves as the handoff signal; outdoor frost timing is not an indoor pod requirement.",
      "es": "Johnny's inicia los alvéolos de cebollín 6–8 semanas antes de la última helada y trasplanta el grupo de 3–4 plántulas. Para Garden, usa un grupo erguido con raíces y hojas activas como señal de paso; el calendario de heladas no es un requisito de pod interior."
    },
    "sources": [
      {
        "id": "johnnys-chives",
        "title": "Chives — Key Growing Information",
        "url": "https://www.johnnyseeds.com/growers-library/herbs/chives/chives-key-growing-information.html"
      }
    ]
  },
  "common-mint": {
    "short": {
      "en": "Move at first true leaves",
      "es": "Mueve a las primeras hojas verdaderas"
    },
    "guidance": {
      "en": "Johnny's recommends moving mint seedlings into individual containers when the first true leaves appear. Garden should also require roots that hold the medium and active, upright growth.",
      "es": "Johnny's recomienda mover las plántulas de menta a recipientes individuales cuando aparezcan las primeras hojas verdaderas. Garden también debe exigir raíces que sostengan el medio y crecimiento activo y erguido."
    },
    "sources": [
      {
        "id": "johnnys-mint",
        "title": "Mint — Key Growing Information",
        "url": "https://www.johnnyseeds.com/growers-library/herbs/mint/mint-key-growing-information.html"
      }
    ]
  },
  "common-purslane-portulaca-oleracea": {
    "short": {
      "en": "Harvest young and prevent unwanted spread",
      "es": "Cosecha joven y evita su expansión no deseada"
    },
    "guidance": {
      "en": "UW Extension supports harvesting at 6–8 weeks and cutting stems for regrowth. Remove unwanted seed heads and do not leave moist stem fragments where they can root. Because common purslane can become a persistent weed, containment is part of responsible establishment.",
      "es": "UW Extension respalda cosechar a las 6–8 semanas y cortar tallos para que rebrote. Retira cabezuelas no deseadas y no dejes fragmentos húmedos de tallo donde puedan enraizar. Como la verdolaga común puede convertirse en maleza persistente, contenerla forma parte de un establecimiento responsable."
    },
    "sources": [
      {
        "id": "uw-purslane-500",
        "title": "Common Purslane, Portulaca oleracea",
        "url": "https://hort.extension.wisc.edu/articles/common-purslane-portulaca-oleracea/"
      },
      {
        "id": "uf-ifas-purslane-500",
        "title": "Purslane: The Reigning Champion of Vitamins A and E among Vegetables and a Potential Crop for Home Gardens (HS1484)",
        "url": "https://ask.ifas.ufl.edu/publication/HS1484"
      }
    ]
  },
  "common-sorrel-rumex-acetosa": {
    "short": {
      "en": "Plant out after hardening off",
      "es": "Planta afuera después de aclimatar"
    },
    "guidance": {
      "en": "The RHS advises hardening off indoor starts before planting outdoors in late spring or early summer. It recommends rich, moisture-retentive soil for leaf production and watering seedlings during dry spells until rooted. Its sun, spacing, and container instructions apply to the sorrel group; no hydroponic transition is documented.",
      "es": "La RHS aconseja aclimatar las plántulas de interior antes de plantarlas al aire libre a fines de primavera o principios de verano. Recomienda suelo rico que retenga humedad para producir hojas y regar las plántulas durante periodos secos hasta que enraícen. Las indicaciones de sol, separación y contenedor se aplican al grupo de acederas; no se documenta transición hidropónica."
    },
    "sources": [
      {
        "id": "rhs-sorrel-growing-500",
        "title": "How to grow sorrel",
        "url": "https://www.rhs.org.uk/herbs/sorrel/grow-your-own"
      }
    ]
  },
  "corn-salad-valeriana-locusta": {
    "short": {
      "en": "Allow about 2–3 weeks after emergence before first harvest",
      "es": "Espera aproximadamente 2–3 semanas tras emerger para la primera cosecha"
    },
    "guidance": {
      "en": "USU states that harvest can begin two to three weeks after emergence or transplanting. It describes harvesting leaves from plants around 4 inches across or cutting the whole plant at 2–3 inches tall. Outdoor bed spacing in the guide is not indoor pod spacing.",
      "es": "USU indica que la cosecha puede comenzar dos o tres semanas después de emerger o trasplantar. Describe cosechar hojas cuando la planta mide unos 4 pulgadas de ancho o cortar la planta completa cuando alcanza 2–3 pulgadas de altura. Las distancias de bancal exterior no equivalen a separación de pods interior."
    },
    "sources": [
      {
        "id": "usu-lambs-lettuce-500",
        "title": "How to Grow Lamb's Lettuce in Your Garden",
        "url": "https://extension.usu.edu/yardandgarden/research/lambs-lettuce-in-the-garden"
      }
    ]
  },
